    FLOG_INFO("[GMCharacterEditorVM:LoadRaceTableData] CfgList: %d ------------------------------>", #CfgList)
    for _, CfgItem in ipairs(CfgList) do
        FLOG_INFO("[GMCharacterEditorVM:LoadRaceTableData] ID:%d, RaceName:%s, RaceID:%d, TribeName:%s, Tribe:%d, Gender:%d, Height:%.2f"
            , CfgItem.ID, CfgItem.RaceName, CfgItem.RaceID, CfgItem.TribeName, CfgItem.Tribe, CfgItem.Gender, CfgItem.Height)
        self:CheckAndInsert(AttachTypeList, CfgItem.AttachType)
        --self:CheckAndInsert(TribeNameList, CfgItem.TribeName)
        --self:CheckAndInsert(GenderList, CfgItem.Gender)
        --self:CheckAndInsert(HeightList, CfgItem.Height)

        if TribeMap[CfgItem.AttachType] == nil then
            TribeMap[CfgItem.AttachType] = {}
        end
        self:CheckAndInsert(TribeMap[CfgItem.AttachType], CfgItem.TribeName)

        self.TribeNameToTribeMap[CfgItem.TribeName] = CfgItem.Tribe
    end

    self.GMCharacterEditorVM.AttachTypeList = AttachTypeList
