end

function GMCharacterEditorMgr:LoadEquipTableData()
    --- ID,ModelName,PartName,ImageChangeID,MaterialID,DecalID,SoundID,EffectID,MaterialAnimationID,AttributeA,AttributeB,AttributeC,AttributeD,AttributeE,AttributeF,AttributeG,AttributeH,AttributeI,AttributeJ
    local CfgList = {}
    if CommonUtil.IsWithEditor() then
        ---@type ImagechangeEditorCfg[]
        CfgList = ImagechangeEditorCfg:FindAllCfg()
    else
        ---@type ImagechangeCfg[]
        CfgList = ImagechangeCfg:FindAllCfg()
    end

    if CfgList == nil then
        FLOG_WARNING("[GMCharacterEditorVM:LoadEquipTableData] CfgList is nil")
        return
    end

    local MetList = { "-" } -- 头部
    local TopList = { "-" } -- 身体
    local GlvList = { "-" } -- 手腕
    local DwnList = { "-" } -- 脚部
    local ShoList = { "-" } -- 足部
    local EarList = { "-" } -- 耳环
    local NekList = { "-" } -- 项链
    local WrsList = { "-" } -- 手链
    local RirList = { "-" } -- 右戒
    local RilList = { "-" } -- 左戒
    local BodyList = { "-" } -- 武器
    local WeaponModelToImageMap = {}

    local PartToLists = {
        met = MetList,
        top = TopList,
        glv = GlvList,
        dwn = DwnList,
        sho = ShoList,
        ear = EarList,
        nek = NekList,
        wrs = WrsList,
        rir = RirList,
        ril = RilList,
        Body = BodyList
    }

    local PartMapToLists = {
        met = {},
        top = {},
        glv = {},
        dwn = {},
        sho = {},
        ear = {},
        nek = {},
        wrs = {},
        rir = {},
        ril = {},
        Body = {}
    }

    --self:CheckAndInsert(PartToLists["Body"], "-")
    PartMapToLists["met"]["-"] = { "-" }
    PartMapToLists["top"]["-"] = { "-" }
    PartMapToLists["glv"]["-"] = { "-" }
    PartMapToLists["dwn"]["-"] = { "-" }
    PartMapToLists["sho"]["-"] = { "-" }
    PartMapToLists["ear"]["-"] = { "-" }
    PartMapToLists["nek"]["-"] = { "-" }
    PartMapToLists["wrs"]["-"] = { "-" }
    PartMapToLists["rir"]["-"] = { "-" }
    PartMapToLists["ril"]["-"] = { "-" }
    PartMapToLists["Body"]["-"] = { "-" }
    WeaponModelToImageMap["--"] = {}
    self:CheckAndInsert(WeaponModelToImageMap["--"], "-")

    FLOG_INFO("[GMCharacterEditorMgr:LoadEquipTableData] CfgList: %d ------------------------------>", #CfgList)
    for _, CfgItem in ipairs(CfgList) do
        --FLOG_INFO("[GMCharacterEditorVM:LoadEquipTableData] ID:%d, ModelName:%s, PartName:%s, ImageChangeID:%d", CfgItem.ID, CfgItem.ModelName, CfgItem.PartName, CfgItem.ImageChangeID)
        local TargetList = PartToLists[CfgItem.PartName]
        if TargetList then
            --FLOG_INFO("[GMCharacterEditorVM:LoadEquipTableData] ModelName:%s, PartName:%s, ImageChangeID:%d", CfgItem.ModelName, CfgItem.PartName, CfgItem.ImageChangeID)
            -- 过滤亚人数据
            if string.startsWith(CfgItem.ModelName, "m") or string.startsWith(CfgItem.ModelName, "d") then
                goto continue
            end

            if string.startsWith(CfgItem.ModelName, "w") then
                -- 把如wXXXXbXXXX的b前成提取获取wXXXX和bXXXX
                local w = string.match(CfgItem.ModelName, "w%d+")
                local b = string.match(CfgItem.ModelName, "b%d+")
                if w then
                    self:CheckAndInsert(TargetList, w)
                end
                if b then
                    local TargetMap = PartMapToLists[CfgItem.PartName]
                    if TargetMap and w then
                        if TargetMap[w] == nil then
                            TargetMap[w] = {}
                        end
                        self:CheckAndInsert(TargetMap[w], b)
                    end

                    if WeaponModelToImageMap[CfgItem.ModelName] == nil then
                        WeaponModelToImageMap[CfgItem.ModelName] = {}
                    end
                    self:CheckAndInsert(WeaponModelToImageMap[CfgItem.ModelName], CfgItem.ImageChangeID)
                end
                goto continue
            end

            -- Armor
            self:CheckAndInsert(TargetList, CfgItem.ModelName)
        end

        -- Armor
        local TargetMap = PartMapToLists[CfgItem.PartName]
        if TargetMap then
            if TargetMap[CfgItem.ModelName] == nil then
                TargetMap[CfgItem.ModelName] = {}
            end
            self:CheckAndInsert(TargetMap[CfgItem.ModelName], CfgItem.ImageChangeID)
        end

        ::continue::
    end

    self.PartMapToLists = PartMapToLists
    self.WeaponModelToImageMap = WeaponModelToImageMap

    self.GMCharacterEditorVM.MetList = self:SortList(MetList)
    self.GMCharacterEditorVM.TopList = self:SortList(TopList)
    self.GMCharacterEditorVM.GlvList = self:SortList(GlvList)
    self.GMCharacterEditorVM.DwnList = self:SortList(DwnList)
    self.GMCharacterEditorVM.ShoList = self:SortList(ShoList)
    self.GMCharacterEditorVM.EarList = self:SortList(EarList)
    self.GMCharacterEditorVM.NekList = self:SortList(NekList)
    self.GMCharacterEditorVM.WrsList = self:SortList(WrsList)
    self.GMCharacterEditorVM.RirList = self:SortList(RirList)
    self.GMCharacterEditorVM.RilList = self:SortList(RilList)

    local WeaponList = self:SortList(BodyList)
    self.GMCharacterEditorVM.Weapon1List = WeaponList
    self.GMCharacterEditorVM.Weapon2List = WeaponList
end

function GMCharacterEditorMgr:LoadEquipmentColorTableData()
    ---@type DyeColorCfg[]
    local CfgList = DyeColorCfg:FindAllCfg()
    if CfgList == nil then
        FLOG_WARNING("[GMCharacterEditorMgr:UpdateEquipmentColorTableList] CfgList is nil")
        return
    end

    local EquipColorList = {}

    FLOG_INFO("[GMCharacterEditorMgr:UpdateEquipmentColorTableList] CfgList: %d ------------------------------>", #CfgList)
    for _, CfgItem in ipairs(CfgList) do
        local HexColor = WardrobeUtil.Dec2HexColor(CfgItem.Color)
        local ColorItem = {
            ColorID = CfgItem.ID,
            JPDisplayName = CfgItem.JPDisplayName,
            DisplayName = CfgItem.DisplayName,
            Color = CfgItem.Color,
            HexColor = HexColor
        }
        FLOG_INFO("[GMCharacterEditorMgr:UpdateEquipmentColorTableList] ID:%d, JPDisplayName:%s, DisplayName:%s, Color:%d(%s)", CfgItem.ID, CfgItem.JPDisplayName, CfgItem.DisplayName, CfgItem.Color, HexColor)
        self:CheckAndInsert(EquipColorList, ColorItem)
    end

    self.EquipColorList = EquipColorList
end

--- 加载捏脸表数据
function GMCharacterEditorMgr:LoadFaceTableData(Cfg, Map, ValueName)
    local CfgList = Cfg:FindAllCfg()
    if CfgList == nil then
        FLOG_WARNING("[GMCharacterEditorVM:LoadFaceTableData] CfgList is nil")
        return
    end

    FLOG_INFO("[GMCharacterEditorVM:LoadFaceTableData] CfgList: %d ------------------------------>", #CfgList)
    for _, CfgItem in ipairs(CfgList) do
        FLOG_INFO("[GMCharacterEditorVM:LoadFaceTableData] %d : %s", CfgItem.RaceID, CfgItem[ValueName])
        if Map[CfgItem.RaceID] == nil then
            Map[CfgItem.RaceID] = {}
        end
        self:CheckAndInsert(Map[CfgItem.RaceID], CfgItem[ValueName])
    end
end

