--- 种族选择变化
---@param RaceID number ProtoCommon.race_type
function GMCharacterEditorMgr:OnAttachTypeChanged(AttachType)
    if string.isnilorempty(AttachType) then
        FLOG_WARNING("[GMCharacterEditorVM:OnAttachTypeChanged] AttachType is nil")
        return
    end

    self.AttachType = AttachType
    self.GMCharacterEditorVM.TribeNameList = self.TribeMap[AttachType]

    local RaceID, Gender = RaceCfg:GetRaceIDByAttachType(AttachType)
    if self.CurRaceID == RaceID and self.CurGender == Gender then
        FLOG_WARNING("[GMCharacterEditorVM:OnAttachTypeChanged] Same RaceID or Gender")
        return
    end

    FLOG_INFO("[GMCharacterEditorMgr:OnAttachTypeChanged] AttachType:%s, RaceID:%d, Gender:%d", AttachType, RaceID, Gender)
    self.CurRaceID = RaceID
    self.CurGender = Gender

    local GenderList
    if Gender == 1 then
        GenderList = { "男" }
    else
        GenderList = { "女" }
    end
    self.GMCharacterEditorVM.GenderList = GenderList
end

function GMCharacterEditorMgr:OnTribeChanged(TribeName)
    if string.isnilorempty(TribeName) then
        FLOG_WARNING("[GMCharacterEditorVM:OnTribeChanged] TribeName is nil")
        return
    end

    local TribeID = self.TribeNameToTribeMap[TribeName]
    if self.CurTribeID == TribeID then
        FLOG_WARNING("[GMCharacterEditorVM:OnTribeChanged] SameID")
        return
    end

    FLOG_INFO("[GMCharacterEditorMgr:OnTribeChanged] %d", TribeID or -1)
    self.CurTribeID = TribeID

    self:OnRaceTribeGenderChanged()
end

