end

function GMCharacterEditorMgr:OnRaceTribeGenderChanged()
    local RaceID = self.CurRaceID
    local TribeID = self.CurTribeID
    local Gender = self.CurGender
    if not RaceID or not TribeID or not Gender then
        return
    end
    if RaceID <= 0 or TribeID <= 0 or Gender <= 0 then
        return
    end

    self:InitUIColorData()

    FLOG_INFO("[GMCharacterEditorMgr:OnRaceTribeGenderChanged] RaceID:%d, TribeID:%d, Gender:%d", RaceID, TribeID, Gender)

    self.GMCharacterEditorVM.HairList = self:GetDataByRaceTribeGender(HairCfg, RaceID, TribeID, Gender, "ModelID")
    self.GMCharacterEditorVM.FaceList = self:GetDataByRaceTribeGender(FaceCfg, RaceID, TribeID, Gender, "ModelName")
    self.GMCharacterEditorVM.FaceDecalList = self:GetDataByRaceTribeGender(FaceDecalCfg, RaceID, TribeID, Gender, "ModelName")

    self.GMCharacterEditorVM:UpdateTableList("FaceContour", self:GetDataByRaceTribeGender(FaceContourCfg, RaceID, TribeID, Gender, "TypeID"))
    self.GMCharacterEditorVM:UpdateTableList("Eye", self:GetDataByRaceTribeGender(EyeCfg, RaceID, TribeID, Gender, "TypeID"))
    self.GMCharacterEditorVM:UpdateTableList("Eyebrow", self:GetDataByRaceTribeGender(EyebrowCfg, RaceID, TribeID, Gender, "TypeID"))
    self.GMCharacterEditorVM:UpdateTableList("Nose", self:GetDataByRaceTribeGender(NoseCfg, RaceID, TribeID, Gender, "TypeID"))
    self.GMCharacterEditorVM:UpdateTableList("Lips", self:GetDataByRaceTribeGender(LipsCfg, RaceID, TribeID, Gender, "TypeID"))

    self.GMCharacterEditorVM.FaceEarList = self:GetDataByRaceTribeGender(EarCfg, RaceID, TribeID, Gender, "TypeID")
    self.GMCharacterEditorVM.TailList = self:GetDataByRaceTribeGender(TailCfg, RaceID, TribeID, Gender, "TypeID")

    self:UpdateColorDataList(RaceID, TribeID, Gender)

    EventMgr:SendEvent(EventID.GMCRaceTribeGenderChanged)

    if self.bIsManual then
        local AvatarComp = MajorUtil.GetMajorAvatarComponent()
        if AvatarComp then
            AvatarComp:ChangeAttachType(self.AttachType, TribeID, Gender)
        end
    end
end

function GMCharacterEditorMgr:GetDataByRaceTribeGender(Cfg, RaceID, TribeID, Gender, ValueName)
    local CfgList = nil
    if Cfg == HairCfg then
        CfgList = Cfg:FindAllCfgByRaceIDTribeGender(RaceID, TribeID, Gender)
    else
        CfgList = Cfg:FindCfgByRaceIDTribeGender(RaceID, TribeID, Gender)
    end
    if CfgList == nil then
        return {}
    end

    local DataList = {}
    for _, CfgItem in ipairs(CfgList) do
        local Item = CfgItem[ValueName]
        if Item then
            --if ValueName == "ModelID" then
            --    FLOG_INFO("[GMCharacterEditorVM:GetDataByRaceTribeGender] ModelID:%d, ModelName:%s", CfgItem.ModelID, CfgItem.ModelName)
            --end
            if ValueName == "ModelName" then
                local Match = Item:match("%d+")
                if Match then
                    Item = Match
                end
            end
            self:CheckAndInsert(DataList, Item)
        end
    end

    --if ValueName == "ModelName" then
    --    self:SortList(DataList)
    --else -- elseif ValueName == "TypeID" or ValueName == "ModelID" then
    --    table.sort(DataList)
    --end
    table.sort(DataList)
    return DataList
end

function GMCharacterEditorMgr:OnFaceChanged(PartKey, ID)
    if self.bIsManual == false then
        --FLOG_WARNING("[GMCharacterEditorVM:OnFaceChanged] bIsManual is false")
        return
    end

    local MajorActor = MajorUtil.GetMajor()
    if MajorActor then
        local AvatarComp = MajorActor:GetAvatarComponent()
        if AvatarComp then
            AvatarComp:SetAvatarPartCustomize(PartKey, ID, false)
        end
    end
end

