function GMCharacterEditorMgr:GetRaceColorID(ColorID)
    local RaceID = self.CurRaceID
    local TribeID = self.CurTribeID
    local Gender = self.CurGender
    if not RaceID or not TribeID or not Gender then
        return
    end
    if RaceID <= 0 or TribeID <= 0 or Gender <= 0 then
        return
    end

    local Race = RaceID -1
    local Tribe = TribeID
    local Sex = Gender == 1 and 0 or 1 -- Gender(1,2):(0,1)
    local bIsSubsp = Tribe % 2 == 1 and 0 or 1
    local Prefix = (Race * 2 + bIsSubsp) * 2 + Sex;
    return Prefix * 1000 + ColorID + 1
end

function GMCharacterEditorMgr:InitUIColorData()
    local List = {}
    local Low = self:GetRaceColorID(0)
    local High = self:GetRaceColorID(192)

    local ColorRaceCfg = RacecolorRaceUiCfg:FindRangeColorCfg(Low, High)
    List[ProtoCommon.avatar_personal.AvatarPersonalHairColor] = {}
    List[ProtoCommon.avatar_personal.AvatarSkinColor] = {}
    for _, v in ipairs(ColorRaceCfg) do
        List[ProtoCommon.avatar_personal.AvatarPersonalHairColor][v.ID] = {R = v.HairR, G = v.HairG, B = v.HairB, A = v.HairA}
        List[ProtoCommon.avatar_personal.AvatarSkinColor][v.ID] = {R = v.SkinR, G = v.SkinG, B = v.SkinB, A = v.SkinA}
    end

    local ColorCommonCfg = RacecolorCommonUiCfg:FindAllColorCfg()
    List[ProtoCommon.avatar_personal.AvatarLeftEyeColor] = {}
    List[ProtoCommon.avatar_personal.AvatarRightEyeColor] = {}
    List[ProtoCommon.avatar_personal.AvatarHairVariationColor] = {}
    List[ProtoCommon.avatar_personal.AvatarLipsColor] = {}
    List[ProtoCommon.avatar_personal.AvatarFaceDecalColor] = {}
    List[ProtoCommon.avatar_personal.AvatarOptionColor] = {}
    for i, v in ipairs(ColorCommonCfg) do
        List[ProtoCommon.avatar_personal.AvatarLeftEyeColor][i] = {R = v.EyeR, G = v.EyeG, B = v.EyeB, A = v.EyeA}
        List[ProtoCommon.avatar_personal.AvatarRightEyeColor][i] = {R = v.EyeR, G = v.EyeG, B = v.EyeB, A = v.EyeA}
        List[ProtoCommon.avatar_personal.AvatarHairVariationColor][i] = {R = v.HairHighlightsR, G = v.HairHighlightsG, B = v.HairHighlightsB, A = v.HairHighlightsA}
        List[ProtoCommon.avatar_personal.AvatarLipsColor][i] = {R = v.LipR, G = v.LipG, B = v.LipB, A = v.LipA}
        List[ProtoCommon.avatar_personal.AvatarFaceDecalColor][i] = {R = v.DecalR, G = v.DecalG, B = v.DecalB, A = v.DecalA}
        List[ProtoCommon.avatar_personal.AvatarOptionColor][i] = {R = v.OptionR, G = v.OptionG, B = v.OptionB, A = v.OptionA}
    end
    self.UIColorList = List
end

function GMCharacterEditorMgr:GetUIColorListByType(ColorType)
    -- AvatarSkinColor肤色 105、
    -- AvatarLeftEyeColor瞳色 112、AvatarRightEyeColor瞳色 113
    -- AvatarLipsColor唇色 115、
    -- AvatarFaceDecalColor面妆色 118、
    -- AvatarPersonalHairColor发色 2、
    -- AvatarHairVariationColor挑染 127
    if self.UIColorList == nil then return end
    return self.UIColorList[ColorType]
end

function GMCharacterEditorMgr:GenColorList(ColorType, TotalNum, bRaceColor)
    _G.FLOG_INFO("[GMCharacterEditorMgr:GenColorList] ColorType: %d, TotalNum: %d, bRaceColor: %s", ColorType, TotalNum, bRaceColor)

    --if ColorType == ProtoCommon.avatar_personal.AvatarRightEyeColor then
    --    FLOG_INFO("[GMCharacterEditorMgr:GenColorList] ===")
    --end

    --local ColorList = LoginAvatarMgr:GetColorListByType(Type)
    local ColorList = self:GetUIColorListByType(ColorType)
    if ColorList == nil or table.size(ColorList) < TotalNum then
        FLOG_ERROR("[GMCharacterEditorMgr:GenColorList] ColorList error")
        return
    end

    local bLightColor = false
    local ColorDataList = {}
    local LightColorDataList = {}
    for Index = 1, TotalNum do
        --local ColorItemVM = LoginCreateColorItemVM.New()
        -- 种族颜色序号映射
        local RaceIndex = nil
        if bRaceColor == true then
            RaceIndex =  self:GetRaceColorID(Index - 1)
        else
            RaceIndex = Index
        end

        -- 浓淡处理
        local ColorFlag = bLightColor == true and 1 or 0
        --RaceIndex = RaceIndex | (ColorFlag << 7) --浓艳清淡共用一套色板
        local Value = Index - 1 + ColorFlag * 128
        local ColorData = { ColorType = ColorType, Color = ColorList[RaceIndex], DataValue = Value }
        --ColorItemVM:UpdateData(ColorData)
        ColorDataList[#ColorDataList + 1] = ColorData

        --if ColorType == ProtoCommon.avatar_personal.AvatarLipsColor or ColorType == ProtoCommon.avatar_personal.AvatarFaceDecalColor then
        --    Value = Index - 1 + ColorFlag * 128
        --    ColorData = { ColorType = ColorType, Color = ColorList[RaceIndex], DataValue = Value }
        --    LightColorDataList[#LightColorDataList + 1] = ColorData
        --end
    end

    return ColorDataList, LightColorDataList
end

--Type: AvatarSkinColor 肤色, 105, TotalNum: 192, bRaceColor: true
--Type: AvatarLeftEyeColor 瞳色, 112, TotalNum: 192, bRaceColor: false
--Type: AvatarLipsColor 唇色 115, TotalNum: 96, bRaceColor: false
--Type: AvatarFaceDecalColor 面妆色, 118, TotalNum: 96, bRaceColor: false
--Type: 124, TotalNum: 192, bRaceColor: false
--Type: AvatarPersonalHairColor 发色, 2, TotalNum: 192, bRaceColor: true
--Type: AvatarHairVariationColor 挑染, 127, TotalNum: 192, bRaceColor: false
function GMCharacterEditorMgr:UpdateColorDataList(RaceID, TribeID, Gender)
    local AllCustomizeFaceCfg = CustomizeFaceCfg:FindCfgByRaceIDTribeGender(RaceID, TribeID, Gender)
    if AllCustomizeFaceCfg == nil then
        FLOG_ERROR("[GMCharacterEditorMgr:UpdateColorDataList] AllCustomizeFaceCfg error")
        return
    end
    FLOG_INFO("[GMCharacterEditorMgr:UpdateColorDataList] ")

    local LoginAvatarMgr = _G.LoginAvatarMgr
    local ColorTable = {}
    ColorTable[LoginAvatarMgr.CustomizeSubType.SkinColor] = { ProtoCommon.avatar_personal.AvatarSkinColor, "SkinColor", true }
    ColorTable[LoginAvatarMgr.CustomizeSubType.HairColor] = { ProtoCommon.avatar_personal.AvatarPersonalHairColor, "HairColor", true }
    ColorTable[LoginAvatarMgr.CustomizeSubType.EyeColor] = { ProtoCommon.avatar_personal.AvatarLeftEyeColor, "EyeColor", false }
    ColorTable[LoginAvatarMgr.CustomizeSubType.LipColor] = { ProtoCommon.avatar_personal.AvatarLipsColor, "LipColor", false }
    ColorTable[LoginAvatarMgr.CustomizeSubType.FaceDecalColor] = { ProtoCommon.avatar_personal.AvatarFaceDecalColor, "FaceDecalColor", false }

    self.ColorDataMap = {}
    self.SubTypeList = {}

    for _, CustomizeCfg in ipairs(AllCustomizeFaceCfg) do
        if CustomizeCfg.SubType == nil then
            goto continue
        end
        self:CheckAndInsert(self.SubTypeList, CustomizeCfg.SubType)

        if ColorTable[CustomizeCfg.SubType] then
            local ColorType = ColorTable[CustomizeCfg.SubType][1]
            if not ColorType then
                --FLOG_ERROR("[GMCharacterEditorMgr:UpdateColorDataList] ColorType error")
                goto continue
            end

            local ColorList = self:GenColorList(ColorType, CustomizeCfg.MaxValue, ColorTable[CustomizeCfg.SubType][3])
            if not ColorList then
                goto continue
            end

            self.ColorDataMap[ColorType] = ColorList
        end
        ::continue::
    end

    local RightEyeColorList = self:GenColorList(ProtoCommon.avatar_personal.AvatarRightEyeColor, 192, false)
    if RightEyeColorList then
        self.ColorDataMap[ProtoCommon.avatar_personal.AvatarRightEyeColor] = RightEyeColorList
    end

    local HairVariationColorList = self:GenColorList(ProtoCommon.avatar_personal.AvatarHairVariationColor, 192, false)
    if HairVariationColorList then
        self.ColorDataMap[ProtoCommon.avatar_personal.AvatarHairVariationColor] = HairVariationColorList
    end
end

--- 获取颜色列表
---@param ColorType number ProtoCommon.avatar_personal
function GMCharacterEditorMgr:GetColorListByType(ColorType)
    if self.ColorDataMap == nil then return end
    return self.ColorDataMap[ColorType]
end

function GMCharacterEditorMgr:IsContainSubType(Value)
    if self.SubTypeList == nil then return false end
    for _, v in ipairs(self.SubTypeList) do
        if v == Value then
            return true
        end
    end
    return false
end

function GMCharacterEditorMgr:ResetAllCurColorIndex()
    FLOG_INFO("[GMCharacterEditorMgr:ResetAllCurColorIndex]")

    local colorTypeMap = {
        [ProtoCommon.avatar_personal.AvatarSkinColor] = { property = "SkinColorBtn", index = "CurSkinColorIndex" },
        [ProtoCommon.avatar_personal.AvatarPersonalHairColor] = { property = "HairColorBtn", index = "CurHairColorIndex" },
        [ProtoCommon.avatar_personal.AvatarHairVariationColor] = { property = "HairVariationBtn", index = "CurHairVariationColorIndex" },
        [ProtoCommon.avatar_personal.AvatarFaceDecalColor] = { property = "FaceDecalColorBtn", index = "CurFaceDecalColorIndex" },
        [ProtoCommon.avatar_personal.AvatarLeftEyeColor] = { property = "LEyeColorBtn", index = "CurLEyeColorIndex" },
        [ProtoCommon.avatar_personal.AvatarRightEyeColor] = { property = "REyeColorBtn", index = "CurREyeColorIndex" },
        [ProtoCommon.avatar_personal.AvatarLipsColor] = { property = "LipColorBtn", index = "CurLipColorIndex" }
    }

    for ColorType, ColorList in pairs(self.ColorDataMap) do
        if ColorList == nil then
            goto continue
        end

        local config = colorTypeMap[ColorType]
        if config then
            self.GMCharacterEditorVM[config.property] = ColorList[self[config.index]]
            FLOG_INFO("[GMCharacterEditorMgr:ResetAllCurColorIndex] ColorType: %d, index: %d, ColorData:%s", ColorType, self[config.index], ColorList[self[config.index]])
        end

        ::continue::
    end
end

