function GMCharacterEditorMgr:InitEquipStainMap()
    --{
    --    met = {
    --        0 = {Text = "全部", SectionID = 0, ColorID = 0, HexColor = "0xffffffff"},
    --        1 = {Text = "区域1", SectionID = 1, ColorID = 0, HexColor = "0xffffffff"},
    --        ...
    --    },
    --}
    self.EquipStainMap = {
        met = {},
        top = {},
        glv = {},
        dwn = {},
        sho = {},
        ear = {},
        rir = {},
        nek = {},
        wrs = {},
        ril = {}
    }

    for Part, PartStainData in pairs(self.EquipStainMap) do
        for i, SectionStainData in ipairs(self.EquipStainData) do
            if PartStainData[i] == nil then
                PartStainData[i] = {}
            end
            --  {Index = 1, Text = "全部", SectionID = 0, ColorID = 0, HexColor = "FFFFFFFF"},
            PartStainData[i].Index = SectionStainData.Index
            PartStainData[i].Text = SectionStainData.Text
            PartStainData[i].SectionID = SectionStainData.SectionID
            PartStainData[i].ColorID = SectionStainData.ColorID
            PartStainData[i].HexColor = SectionStainData.HexColor
        end
    end
end

function GMCharacterEditorMgr:GetEquipStainList(PartName)
    if self.EquipStainMap[PartName] == nil then
        FLOG_ERROR("[GMCharacterEditorMgr:GetEquipStainList] PartName error")
        return nil
    end

    local DataList = {}
    FLOG_INFO("[GMCharacterEditorMgr:GetEquipStainList] PartName: %s ------------->", PartName)
    for i, SectionStainData in ipairs(self.EquipStainMap[PartName]) do
        DataList[#DataList + 1] = SectionStainData
        FLOG_INFO("[GMCharacterEditorMgr:GetEquipStainList] +++ i: %d, Text: %s, Index: %d, ColorID: %d, HexColor: %s",
                i, SectionStainData.Text, SectionStainData.SectionID, SectionStainData.ColorID, SectionStainData.HexColor)
    end

    return DataList
end

function GMCharacterEditorMgr:SetEquipStainData(PartName, SectionID, ColorID, HexColor)
    if self.EquipStainMap[PartName] == nil then
        FLOG_ERROR("[GMCharacterEditorMgr:SetEquipStainData] PartName error")
        return
    end

    FLOG_INFO("[GMCharacterEditorMgr:SetEquipStainData] PartName: %s, SectionID: %d, ColorID: %d, HexColor: %s", PartName, SectionID, ColorID, HexColor)
    if SectionID == 0 then
        for i = 1, #self.EquipStainMap[PartName] do
            self.EquipStainMap[PartName][i].ColorID = ColorID
            self.EquipStainMap[PartName][i].HexColor = HexColor
        end
    else
        local Index = SectionID + 1
        self.EquipStainMap[PartName][Index].ColorID = ColorID
        self.EquipStainMap[PartName][Index].HexColor = HexColor
    end
end

