function GMCharacterEditorMgr:OnEquipChanged(PartName, ModelName, SelectionType)
    if string.isnilorempty(PartName) then
        FLOG_WARNING("[GMCharacterEditorMgr:OnEquipChanged] PartName is nil")
        return
    end
    if string.isnilorempty(ModelName) then
        FLOG_WARNING("[GMCharacterEditorMgr:OnEquipChanged] ModelName is nil")
        return
    end

    --FLOG_INFO("[GMCharacterEditorMgr:OnEquipChanged] PartName:%s, ModelName:%s", PartName, ModelName)
    local ModelImageChangeList = self.PartMapToLists[PartName]
    if ModelImageChangeList then
        local List = ModelImageChangeList[ModelName]
        table.sort(List, function(a, b)
            return a < b
        end)

        self.CurArmorInfo[PartName].ModelName = ModelName
        self.GMCharacterEditorVM[self:CapitalizeFirst(PartName) .. "ImageList"] = List
    end
end

