        FLOG_WARNING("[GMCharacterEditorMgr:OnWeaponChanged] ModelName is nil")
        return
    end

    --FLOG_INFO("[GMCharacterEditorMgr:OnWeaponChanged] ModelName:%s", ModelName)
    local ModelImageChangeList = self.PartMapToLists["Body"]
