        if bMasterWeapon then
            self.CurWeaponInfo["MasterWeapon"].ModelName = ModelName
            self.GMCharacterEditorVM.Weapon1BList = List
        else
            self.CurWeaponInfo["SlaveWeapon"].ModelName = ModelName
            self.GMCharacterEditorVM.Weapon2BList = List
        end
    end
