function GMCharacterEditorMgr:OnWeaponImageChanged(ImageChangeID, bMasterWeapon, SelectionType)
    if string.isnilorempty(ImageChangeID) then
        FLOG_WARNING("[GMCharacterEditorMgr:OnWeaponImageChanged] ImageChangeID is nil")
        return
    end
    if self.bIsManual == false then
        --FLOG_WARNING("[GMCharacterEditorVM:OnWeaponImageChanged] bIsManual is false")
        return
    end
    --if SelectionType == _G.UE.ESelectInfo.Direct then
    --    FLOG_WARNING("[GMCharacterEditorMgr:OnWeaponImageChanged] SelectionType == _G.UE.ESelectInfo.Direct")
    --    return
    --end

    --FLOG_INFO("[GMCharacterEditorMgr:OnWeaponImageChanged] ImageChangeID:%s", ImageChangeID)
    local ModelPath = ""
    local SubModelPath = ""
    local PosKey = UE.EAvatarPartType.WEAPON_MASTER_HAND
