        ModelPath = self.CurWeaponInfo["MasterWeapon"].ModelName
        SubModelPath = self.CurWeaponInfo["MasterWeapon"].BName
        PosKey = UE.EAvatarPartType.WEAPON_MASTER_HAND
        --self.CurWeaponInfo["MasterWeapon"].ImageChangeID = ImageChangeID
    else
        ModelPath = self.CurWeaponInfo["SlaveWeapon"].ModelName
        SubModelPath = self.CurWeaponInfo["SlaveWeapon"].BName
        PosKey = UE.EAvatarPartType.WEAPON_SLAVE_HAND
        --self.CurWeaponInfo["SlaveWeapon"].ImageChangeID = ImageChangeID
