function GMCharacterEditorMgr:StainPartForSection(AvatarPartType, SectionID, ColorID)
    local AvatarCom = MajorUtil.GetMajorAvatarComponent()
    if AvatarCom then
        local Assembler = AvatarCom:GetAssembler()
        if Assembler then

            AvatarCom:SetPreviewSectionStain(true)

            if SectionID == 0 then
                for i = 1, 16 do
                    FLOG_INFO("[CommonRender2DView:StainPartForSection] AvatarPartType:%s, SectionID:%d, ColorID:%s", tostring(AvatarPartType), i, tostring(ColorID))
                    Assembler:StainPartForSection(AvatarPartType, i, ColorID)
                end
            else
                FLOG_INFO("[CommonRender2DView:StainPartForSection] AvatarPartType:%s, SectionID:%d, ColorID:%s", tostring(AvatarPartType), SectionID - 1, tostring(ColorID))
                Assembler:StainPartForSection(AvatarPartType, tonumber(SectionID) - 1, ColorID)
            end
        end
    end
end

