function GMCharacterEditorMgr:SortList(List)
    local function ExtractNumber(str)
        local numbers = {}
        for num in str:gmatch("%d+") do
            table.insert(numbers, num)
        end
        return tonumber(table.concat(numbers)) or 0
    end

    table.sort(List, function(a, b)
        local aNum = ExtractNumber(a)
        local bNum = ExtractNumber(b)
        return aNum < bNum
    end)
    return List
end

function GMCharacterEditorMgr:CapitalizeFirst(str)
    return (str:gsub("^%l", string.upper))
end

function GMCharacterEditorMgr:ChangeModel(ModelName, PosKey, ImageChangeID)
    local AvatarComp = MajorUtil.GetMajorAvatarComponent()
    if AvatarComp then
        local TargetParts  = _G.UE.TArray(_G.UE.int32)
        TargetParts:Add(PosKey)
        AvatarComp:ClientGMChangeAvatarEquip(ModelName, TargetParts, tonumber(ImageChangeID), 0)
    end
end

return GMCharacterEditorMgr